import {numberCards,specials,penalties,freshHand,details,roundScores} from './scoring.mjs';
const KEY='flip7-score-v1',colors=['#f6d84f','#6dc6c6','#ef8f79','#bca4d2','#add46d','#90b7dd','#f5bc62','#d6b3d0'];
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,names=['','',''],target=200,brutal=false,selected=null,toastTimer,deferredInstall;
const clone=x=>JSON.parse(JSON.stringify(x));
try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.players?.length&&Array.isArray(s.rounds)){
 if(s.version===2)state=s;
 else state={version:2,players:s.players,target:s.target,mode:'standard',rounds:s.rounds.map(r=>r.map(v=>({...freshHand(),manual:v}))),draft:s.draft.map(v=>v===''?freshHand():({...freshHand(),manual:Number(v)})),editing:null,editDraft:null};
}}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{$('#save-state').textContent='Sauvegarde indisponible sur cet appareil'}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function avatar(n,i){return `<span class="avatar" style="--color:${colors[i%colors.length]}">${escape(n.trim().slice(0,1).toUpperCase()||String(i+1))}</span>`}
function hands(){return state.editing===null?state.draft:state.editDraft}
function totals(){return state.players.map((_,i)=>state.rounds.reduce((sum,r)=>sum+roundScores(r,state.mode)[i],0))}
function standings(t){return state.players.map((name,i)=>({name,i,total:t[i]})).sort((a,b)=>b.total-a.total)}
function render(){if(!state)return setup();const t=totals(),rank=standings(t),max=rank[0].total,w=max>=state.target?rank.filter(p=>p.total===max):[],won=w.length===1,scores=roundScores(hands(),state.mode),edit=state.editing!==null;
 $('#main').innerHTML=`<div class="game-top"><div><div class="eyebrow">Vengeance${state.mode==='brutal'?' · Sans pitié':''} · ${state.players.length} joueurs</div><h1>Que le meilleur gagne.</h1><p>Objectif ${state.target} points · ${state.rounds.length} manche${state.rounds.length>1?'s':''} jouée${state.rounds.length>1?'s':''}</p></div><button class="quiet" id="new-game">Nouvelle partie</button></div>${won?`<div class="win"><div class="eyebrow">Partie terminée</div><h2>${escape(w[0].name)} remporte la partie !</h2><p>${max} points. Une revanche ?</p><button class="quiet" id="rematch">Rejouer avec les mêmes joueurs</button></div>`:w.length>1?'<div class="win"><h2>Égalité en tête !</h2><p>Une nouvelle manche pour vous départager.</p></div>':''}<div class="game-grid"><section class="panel"><div class="section-top"><h2>${edit?'Modifier la manche '+(state.editing+1):'Manche '+(state.rounds.length+1)}</h2><span class="tag">${edit?'Correction':'Saisie par cartes'}</span></div>${won&&!edit?'<p class="muted">Retrouvez et corrigez les manches dans l’historique.</p>':`<p class="subtitle">Touchez un joueur, puis ses cartes. Aucune carte = 0 point.</p><div class="round-rows">${state.players.map((n,i)=>`<button class="player-select ${selected===i?'selected':''}" data-player="${i}" aria-label="Cartes de ${escape(n)}" aria-expanded="${selected===i}">${avatar(n,i)}<span class="player-summary"><b>${escape(n)}</b><small>${summary(hands()[i])}</small></span><span class="score">${scores[i]} <small>pts</small></span><span aria-hidden="true">${selected===i?'−':'+'}</span></button>${selected===i?editor(i):''}`).join('')}</div><div class="round-bottom"><button class="primary wide" id="commit"><span>${edit?'Enregistrer la correction':'Terminer la manche'}</span><span class="arrow">↗</span></button>${edit?'<button class="quiet" id="cancel-edit">Annuler la correction</button>':''}<p class="hint">Aucune validation par joueur. Toutes les sélections sont sauvegardées automatiquement.</p></div>`}</section><section class="panel standings-panel"><div class="section-top"><h2>Le classement</h2><span class="tag">${state.target} pts à atteindre</span></div><div class="standings">${rank.map((p,j)=>`<div class="${p.total===max&&max>0?'leader':''}"><div class="standing-head"><span class="rank">${j>0&&rank[j-1].total===p.total?'=':j+1}</span>${avatar(p.name,p.i)}<span class="standing-name">${escape(p.name)}</span><span class="score">${p.total} <small>pts</small></span></div><div class="bar"><div style="width:${Math.max(0,Math.min(100,p.total/state.target*100))}%"></div></div></div>`).join('')}</div></section></div><section class="history"><div class="section-top"><h2>Le fil de la partie</h2>${state.rounds.length?'<button class="quiet" id="undo">Annuler la dernière manche</button>':''}</div>${state.rounds.length?`<div class="table-scroll"><table><thead><tr><th>Manche</th>${state.players.map(n=>`<th>${escape(n)}</th>`).join('')}<th></th></tr></thead><tbody>${state.rounds.map((r,j)=>`<tr><td>${String(j+1).padStart(2,'0')}</td>${roundScores(r,state.mode).map(v=>`<td>${v}</td>`).join('')}<td><button data-edit="${j}" aria-label="Modifier la manche ${j+1}">Modifier</button></td></tr>`).reverse().join('')}</tbody></table></div>`:'<div class="empty">La première manche ouvre le bal.<br>Vos scores et vos cartes apparaîtront ici.</div>'}</section>`;
 $('#new-game').onclick=()=>confirmAction('Une nouvelle partie ?','La partie actuelle sera remplacée.','Nouvelle partie',()=>{names=[...state.players];target=state.target;brutal=state.mode==='brutal';state=null;selected=null;save();render()});
 $('#rematch')?.addEventListener('click',()=>confirmAction('Prêts pour la revanche ?','Les mêmes joueurs repartent de zéro.','Rejouer',()=>{state.rounds=[];state.draft=state.players.map(freshHand);state.editing=null;state.editDraft=null;selected=null;save();render()}));
 document.querySelectorAll('[data-player]').forEach(el=>el.onclick=()=>{selected=selected===+el.dataset.player?null:+el.dataset.player;render()});
 document.querySelectorAll('[data-card]').forEach(el=>el.onclick=()=>toggleCard(el.dataset.card));
 $('#bust')?.addEventListener('click',()=>{const h=hands()[selected];h.bust=!h.bust;h.manual=null;if(h.bust)h.target=null;save();render()});
 $('#clear-hand')?.addEventListener('click',()=>{hands()[selected]=freshHand();save();render()});
 $('#attack-target')?.addEventListener('change',e=>{hands()[selected].target=e.target.value===''?null:Number(e.target.value);save();render()});
 $('#legacy-score')?.addEventListener('input',e=>{const v=Number(e.target.value);if(e.target.value!==''&&Number.isInteger(v)){hands()[selected].manual=v;save();const score=roundScores(hands(),state.mode)[selected];document.querySelector(`[data-player="${selected}"] .score`).innerHTML=`${score} <small>pts</small>`}});
 $('#commit')?.addEventListener('click',()=>{if(hands().filter(h=>details(h,state.mode).flip).length>1)return toast('Un seul joueur peut réaliser un Flip 7 dans une manche.');if(edit){state.rounds[state.editing]=clone(hands());state.editing=null;state.editDraft=null}else{state.rounds.push(clone(state.draft));state.draft=state.players.map(freshHand)}selected=null;save();render();toast('Manche enregistrée')});
 document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{if(state.editing!==null&&state.editing!==+el.dataset.edit)return toast('Enregistrez ou annulez la correction en cours.');state.editing=+el.dataset.edit;state.editDraft=clone(state.rounds[state.editing]);selected=null;save();render();window.scrollTo({top:0,behavior:'smooth'})});
 $('#cancel-edit')?.addEventListener('click',()=>{state.editing=null;state.editDraft=null;selected=null;save();render()});
 $('#undo')?.addEventListener('click',()=>{if(edit)return toast('Terminez d’abord la correction en cours.');confirmAction('Annuler la dernière manche ?','Ses cartes remplaceront la saisie en cours et ses scores seront retirés du classement.','Annuler la manche',()=>{state.draft=state.rounds.pop();selected=null;save();render()})});
}
function summary(h){const d=details(h,state.mode);if(d.legacy)return 'Ancienne saisie de points';if(h.bust)return 'Sauté';if(d.flip)return 'Flip 7 · '+(h.target===null?'+15 points':'vengeance −15');if(!h.cards.length)return 'Aucune carte · 0 point';return `${d.count} carte${d.count>1?'s':''} Numéro${d.zero?' · Zéro : pas de Flip 7':''}`}
function cardButton(c,kind='number'){const on=hands()[selected].cards.includes(c.id);return `<button class="pick-card ${kind} ${on?'picked':''}" data-card="${c.id}" style="--card-color:${["#37b9c7","#edd667","#e6dc3f","#ed6693","#32c0d1","#5caf67","#b17bb6","#ed8065","#a8d966","#f5ae43","#f34b53","#6d9ab9","#e4cf6e","#37a6ce"][Number(c.id)]|| (c.id==='lucky13'?'#3aa7ce':c.id==='unlucky7'?'#babcc5':'#ed7861')}" aria-label="${escape(c.name||'Carte '+c.label)}" aria-pressed="${on}"><b>${c.label}</b>${c.name?`<small>${c.id==='unlucky7'?'Porte-malheur':'Porte-bonheur'}</small>`:''}<span class="check" aria-hidden="true">${on?'✓':'+'}</span></button>`}
function editor(i){const h=hands()[i],d=details(h,state.mode);return `<div class="card-editor" aria-label="Sélection des cartes de ${escape(state.players[i])}">${d.legacy?`<label class="legacy-label">Ancien score (cartes non renseignées)<input id="legacy-score" type="number" step="1" value="${h.manual}"></label><p class="hint">Sélectionner une carte remplace ce score par le calcul automatique.</p>`:''}<div class="editor-top"><span>Cartes Numéro <b>${d.count}/7</b></span><button class="quiet" id="clear-hand">Tout effacer</button></div><div class="card-grid">${numberCards.map(c=>cardButton(c)).join('')}</div><div class="special-grid">${specials.map(c=>cardButton(c,'special')).join('')}</div><p class="hint">Sélectionnez les cartes encore devant le joueur en fin de manche. Le 7 porte-malheur remplace le 7 ordinaire ; il ne réinitialise pas cette saisie.</p><div class="editor-top">Cartes Malus</div><div class="penalty-grid">${penalties.map(c=>cardButton(c,'penalty')).join('')}${cardButton({id:'half',label:'÷2'},'penalty')}</div><button id="bust" class="bust-toggle ${h.bust?'active':''}" aria-pressed="${h.bust}">Sauté ${h.bust?'✓':'?'} <span>${state.mode==='brutal'?'Les malus restent comptés':'0 point pour cette manche'}</span></button>${state.mode==='brutal'&&d.flip?`<label class="attack-label">Bonus Flip 7<select id="attack-target"><option value="">Gagner 15 points</option>${state.players.map((n,j)=>j===i?'':`<option value="${j}" ${h.target===j?'selected':''}>Retirer 15 à ${escape(n)}</option>`).join('')}</select></label>`:''}<div class="calculation" aria-live="polite">${d.legacy?'Ancien score conservé':h.bust?(state.mode==='brutal'?`Sauté · malus : ${d.score} points`:'Sauté → 0 point'):d.zero?`Carte 0 sans Flip 7 → ${d.score} point${d.score===0?'':'s'}`:`${d.sum} (numéros)${d.penalty?' − '+d.penalty+' (malus)':''}${d.half?' → ÷2, arrondi inférieur':''}${d.bonus?' + 15 (Flip 7)':''} = <b>${d.score} points</b>`}${d.flip&&h.target!==null?' · −15 pour '+escape(state.players[h.target]):''}</div><p class="hint">Le bonus s’ajoute automatiquement à 7 cartes Numéro, y compris les deux 13 avec le porte-bonheur.</p></div>`}
function toggleCard(id){const h=hands()[selected];h.manual=null;if(h.cards.includes(id)){h.cards=h.cards.filter(c=>c!==id)}else{
 const numeric=[...numberCards,...specials].some(c=>c.id===id),other=id==='7'?'unlucky7':id==='unlucky7'?'7':null;
 const count=details(h,state.mode).count;if(numeric&&count>=7&&!(other&&h.cards.includes(other)))return toast('Un Flip 7 contient 7 cartes Numéro au maximum.');
 if(other)h.cards=h.cards.filter(c=>c!==other);h.cards.push(id);
 }if(!details(h,state.mode).flip)h.target=null;save();render();}
function setup(){$('#main').innerHTML=`<div class="setup"><section class="intro"><div class="eyebrow">Votre carnet de partie</div><h1>Les cartes en main.<br>Les comptes ici.</h1><p>Moins de calculs, plus de revanche.<br>On s’occupe des points.</p><div class="art" aria-hidden="true"><div class="playing-card card-a" data-num="4">4</div><div class="playing-card card-b" data-num="7">7</div><div class="playing-card card-c" data-num="13">13</div><span class="art-caption">Un dernier tour… et on s’arrête ?</span></div></section><section class="panel"><div class="panel-top"><h2>Autour de la table</h2><span class="tag">Vengeance</span></div><p class="subtitle">Qui tente sa chance aujourd’hui ?</p><form id="setup-form"><div class="players-inputs">${names.map((n,i)=>`<div class="player-input">${avatar(n,i)}<input maxlength="24" aria-label="Nom du joueur ${i+1}" placeholder="Joueur ${i+1}" value="${escape(n)}" data-name="${i}"><button type="button" class="remove" data-remove="${i}" aria-label="Retirer le joueur ${i+1}" ${names.length<=1?'disabled':''}>×</button></div>`).join('')}</div><button type="button" class="add" id="add" ${names.length>=18?'disabled':''}>+ Ajouter un joueur</button><div class="settings"><label for="target">Objectif de la partie <span class="muted">· points</span></label><input type="number" id="target" value="${target}" min="1" max="9999" step="1" inputmode="numeric" required></div><label class="mode-setting"><input id="brutal" type="checkbox" ${brutal?'checked':''}> Mode Sans pitié <span class="muted">Scores négatifs et vengeance −15</span></label><button class="primary wide" type="submit"><span>C’est parti</span><span class="arrow">↗</span></button></form><p class="hint">Un appareil pour toute la table. Installation et jeu hors connexion disponibles via le bouton Installer en haut.</p></section></div>`;
document.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>{names[+el.dataset.name]=el.value;el.previousElementSibling.textContent=el.value.trim().slice(0,1).toUpperCase()||+el.dataset.name+1});$('#target').oninput=e=>target=Number(e.target.value);$('#brutal').onchange=e=>brutal=e.target.checked;document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{names.splice(+el.dataset.remove,1);setup()});$('#add').onclick=()=>{names.push('');setup();document.querySelector('[data-name="'+(names.length-1)+'"]').focus()};$('#setup-form').onsubmit=e=>{e.preventDefault();if(!Number.isInteger(target)||target<1||target>9999)return;const players=names.map((n,i)=>n.trim()||'Joueur '+(i+1));if(new Set(players.map(n=>n.toLocaleLowerCase())).size!==players.length)return toast('Choisissez un nom différent pour chaque joueur.');state={version:2,players,target,mode:brutal?'brutal':'standard',rounds:[],draft:players.map(freshHand),editing:null,editDraft:null};selected=null;save();render();window.scrollTo(0,0)};}
function dialog(html){const el=$('#modal');el.innerHTML=html;el.showModal();el.querySelector('[data-close]')?.addEventListener('click',()=>el.close())}
function confirmAction(title,body,label,fn){dialog(`<h2>${title}</h2><p>${body}</p><div class="dialog-actions"><button class="quiet" data-close>Retour</button><button class="primary" id="confirm">${label}</button></div>`);$('#confirm').onclick=()=>{$('#modal').close();fn()}}
$('#help').onclick=()=>dialog(`<div class="eyebrow">Mode d’emploi</div><h2>Touchez. Comptez. Jouez.</h2><p>Touchez un joueur et sélectionnez les cartes qu’il possède en fin de manche. Retouchez une carte pour la retirer. Le score et le bonus Flip 7 sont automatiques. Un joueur sans sélection marque 0 : inutile de l’ouvrir ou de le valider.</p><p>Le calcul suit le livret français p.6 : somme des numéros, retrait des malus (minimum 0 en mode normal), puis ÷2 arrondi à l’inférieur, et enfin bonus de 15.</p><p>Le zéro impose 0 sans Flip 7. Le 13 porte-bonheur et un 13 ordinaire valent 26 et comptent comme deux cartes. Saisissez les cartes finales après les vols, échanges et défausses ; les cartes Action ne se comptent pas.</p><p>Terminez la manche pour enregistrer les scores. « Modifier » dans l’historique permet de retrouver toutes ses cartes. Vous pouvez annuler une correction. Les anciennes manches conservent leurs scores.</p><p>Le mode Sans pitié se choisit à la création de la partie : scores négatifs, malus sur un joueur ayant sauté et choix du bonus +15 ou d’une vengeance −15 sur un adversaire.</p><p>Les données restent sur cet appareil. Installez l’application via le bouton Installer ; attendez « Prêt hors connexion » avant de couper Internet.</p><p><a href="https://flip-7.com/flip7-vengeance/" target="_blank" rel="noopener">Règles officielles ↗</a></p><p class="hint">Compteur indépendant, sans affiliation avec les éditeurs.</p><button class="primary wide" data-close>Compris</button>`);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('Application installée')});
$('#install').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return}dialog(`<div class="eyebrow">Toujours à portée de main</div><h2>Installer Flip 7</h2><p><b>iPhone / iPad :</b> ouvrez cette adresse dans Safari, puis touchez Partager → Sur l’écran d’accueil → Ajouter. Activez « Ouvrir comme app » si proposé.</p><p><b>Android :</b> ouvrez dans Chrome, puis menu ⋮ → Installer l’application ou Ajouter à l’écran d’accueil.</p><p>Ouvrez une première fois avec Internet et attendez « Prêt hors connexion ». Vous pourrez ensuite lancer l’application depuis son icône en mode avion.</p><p>Les parties restent sur cet appareil ; l’installation peut créer un espace de stockage distinct selon le navigateur.</p><button class="primary wide" data-close>Compris</button>`)};
render();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async reg=>{await navigator.serviceWorker.ready;const worker=navigator.serviceWorker.controller||reg.active;worker?.postMessage({type:'CHECK_OFFLINE'});reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='activated')w.postMessage({type:'CHECK_OFFLINE'})})})}).catch(()=>{$('#offline-state').textContent='Hors connexion indisponible'});navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_READY')$('#offline-state').textContent='Prêt hors connexion'});navigator.serviceWorker.addEventListener('controllerchange',()=>navigator.serviceWorker.controller?.postMessage({type:'CHECK_OFFLINE'}))}
